#include <functional>
#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    int number = 2;
    std::reference_wrapper ref{number};
    std::reference_wrapper<int> other{number};
    other = ref;
    other.get() = 3;
    assert(number == 3);
    {
        std::function<int(int)> function = [](int n) { return n + 1; };
        assert(function(3) == 4);
    }
}
